/* Shared real spell-class engine plus actual paired-artifact source and controller. */
import fs from 'node:fs';import vm from 'node:vm';
import {createInstrumentCaster} from './instrument-cast-native.mjs';
import *as model from '../../src/data/lib/vecna-grafts.js';import *as profiles from '../../src/data/lib/vecna-graft-profiles.js';import *as source from '../../src/data/lib/vecna-graft-source.js';
import {createVecnaGraftsController} from '../../src/data/lib/vecna-graft-controller.js';
const read=p=>fs.readFileSync(new URL('../../src/'+p,import.meta.url),'utf8'),strip=s=>s.replace(/^import [^\n]*\n/gm,'').replace(/^export /gm,'');
export function createVecnaInstrumentEngine(options={}){let post;const client=createInstrumentCaster({...options,beforeInstrumentPost:ctx=>post?.run(ctx)}),e=client.engine,c=e.c;Object.assign(c,model,profiles,source,{createVecnaGraftsController});const fxNative=vm.createContext({DataEnv:{slot:{GX:structuredClone(c.GX),FXO:structuredClone(c.FXO)}}});fxNative.GX=fxNative.DataEnv.slot.GX;fxNative.FXO=fxNative.DataEnv.slot.FXO;vm.runInContext(read('data/fx-L4.js'),fxNative);c.GX=structuredClone(fxNative.DataEnv.slot.GX);c.FXO=structuredClone(fxNative.DataEnv.slot.FXO);c.genv.GX=c.GX;c.genv.FXO=c.FXO;const fxSources=[],priorFxRegister=c.registerFxSource;c.registerFxSource=g=>fxSources.push(g);vm.runInContext(strip(read('builder/11b-logic-fx-sources.js')),c);c.registerFxSource=priorFxRegister;c.fxList=()=>fxSources.find(g=>g.id==='items').collect({G:c.GX,TL:c.TL()}).flatMap(g=>g.list);
const helper=read('builder/10w-logic-vecna-grafts.js'),exports=[...helper.matchAll(/export function (\w+)/g)].map(m=>m[1]);vm.runInContext('(function(){'+strip(helper)+';Object.assign(globalThis,{'+exports.join(',')+'})})()',c);c.registerSheetGroup=g=>post=g;vm.runInContext(strip(read('builder/12zj-logic-vecna-grafts.js')),c);e.setC(e.project());vm.runInContext('(function(){'+strip(read('builder/25t-logic-vecna-grafts.js'))+'})()',c);
const command=(kind,body)=>{const info=c.genv.__bldVecnaGraftsInfo(e.C.name),token=c.genv.__bldVecnaGraftsCapture(e.C.name,{signature:info.signature});return c.genv.__bldVecnaGraftsCommand(token,kind,body,e.before,()=>true)};
return {e,client,command};}
